 1→import Keycloak from 'keycloak-js'
 2→
 3→const keycloak = new Keycloak({
 4→  url: import.meta.env.VITE_KEYCLOAK_URL || 'http://localhost:8080',
 5→  realm: import.meta.env.VITE_KEYCLOAK_REALM || 'upomgtu',
 6→  clientId: import.meta.env.VITE_KEYCLOAK_CLIENT_ID || 'upomgtu',
 7→})
 8→
 9→export async function initAuth(): Promise<boolean> {
10→  const authenticated = await keycloak.init({
11→    onLoad: 'login-required',
12→    checkLoginIframe: false,
13→  })
14→
15→  if (authenticated) {
16→    // Auto-refresh token before it expires
17→    setInterval(async () => {
18→      try {
19→        await keycloak.updateToken(30)
20→      } catch {
21→        keycloak.login()
22→      }
23→    }, 10_000)
24→  }
25→
26→  return authenticated
27→}
28→
29→export function getToken(): string | undefined {
30→  return keycloak.token
31→}
32→
33→export function logout(): void {
34→  keycloak.logout({ redirectUri: window.location.origin })
35→}
36→
37→export { keycloak }
