 1→using System.ComponentModel.DataAnnotations;
 2→
 3→namespace OmgtuPortal;
 4→
 5→public sealed class AppSettings
 6→{
 7→    [Required]
 8→    public required string DatabaseUrl { get; init; }
 9→
10→    [Required]
11→    public required string KeycloakUrl { get; init; }
12→
13→    [Required]
14→    public required string KeycloakRealm { get; init; }
15→
16→    [Required]
17→    public required string KeycloakClientId { get; init; }
18→
19→    [Required]
20→    public required string CorsOrigins { get; init; }
21→
22→    public bool AutoLogin { get; init; }
23→
24→    public string? UniversityProvider { get; init; }
25→    public string? UniversityBaseUrl { get; init; }
26→
27→    public string Authority => $"{KeycloakUrl.TrimEnd('/')}/realms/{KeycloakRealm}";
28→
29→    public static AppSettings FromEnvironment()
30→    {
31→        var settings = new AppSettings
32→        {
33→            DatabaseUrl = GetRequired("DATABASE_URL"),
34→            KeycloakUrl = GetRequired("KEYCLOAK_URL"),
35→            KeycloakRealm = GetRequired("KEYCLOAK_REALM"),
36→            KeycloakClientId = GetRequired("KEYCLOAK_CLIENT_ID"),
37→            CorsOrigins = GetRequired("CORS_ORIGINS"),
38→            AutoLogin = Environment.GetEnvironmentVariable("AUTOLOGIN")?.Equals("true", StringComparison.OrdinalIgnoreCase) ?? false,
39→            UniversityProvider = Environment.GetEnvironmentVariable("UNIVERSITY_PROVIDER"),
40→            UniversityBaseUrl = Environment.GetEnvironmentVariable("UNIVERSITY_BASE_URL"),
41→        };
42→
43→        Validate(settings);
44→        return settings;
45→    }
46→
47→    private static string GetRequired(string name)
48→    {
49→        return Environment.GetEnvironmentVariable(name)
50→               ?? throw new InvalidOperationException(
51→                   $"Required environment variable '{name}' is not set. Check your .env file.");
52→    }
53→
54→    private static void Validate(AppSettings settings)
55→    {
56→        var context = new ValidationContext(settings);
57→        var results = new List<ValidationResult>();
58→
59→        if (!Validator.TryValidateObject(settings, context, results, validateAllProperties: true))
60→        {
61→            var errors = string.Join(Environment.NewLine, results.Select(r => r.ErrorMessage));
62→            throw new InvalidOperationException(
63→                $"AppSettings validation failed:{Environment.NewLine}{errors}");
64→        }
65→    }
66→}
