import { createRouter, createWebHistory } from 'vue-router'
import { useToast } from 'vue-toastification'
import { getUserRoles } from './auth'

import HomePage from './pages/HomePage.vue'
import TeacherDashboard from './pages/TeacherDashboard.vue'
import TeacherStudents from './pages/TeacherStudents.vue'

declare module 'vue-router' {
  interface RouteMeta {
    requiredRole?: string
  }
}

const router = createRouter({
  history: createWebHistory(),
  routes: [
    {
      path: '/',
      name: 'home',
      component: HomePage,
    },
    {
      path: '/teacher',
      name: 'teacher',
      component: TeacherDashboard,
      meta: { requiredRole: 'teacher' },
    },
    {
      path: '/teacher/students',
      name: 'teacher-students',
      component: TeacherStudents,
      meta: { requiredRole: 'teacher' },
    },
  ],
})

router.beforeEach((to) => {
  const requiredRole = to.meta.requiredRole
  if (!requiredRole) return true

  const roles = getUserRoles()
  if (roles.includes(requiredRole)) return true

  const toast = useToast()
  toast.error(`Доступ запрещён: требуется роль «${requiredRole}»`)
  return { name: 'home' }
})

export default router

