import Keycloak from 'keycloak-js'

const keycloak = new Keycloak({
  url: import.meta.env.VITE_KEYCLOAK_URL || 'http://localhost:8080',
  realm: import.meta.env.VITE_KEYCLOAK_REALM || 'upomgtu',
  clientId: import.meta.env.VITE_KEYCLOAK_CLIENT_ID || 'upomgtu',
})

export async function initAuth(): Promise<boolean> {
  const authenticated = await keycloak.init({
    onLoad: 'login-required',
    checkLoginIframe: false,
  })

  // Clean up Keycloak auth params from URL after redirect
  if (window.location.hash.includes('state=') || window.location.hash.includes('session_state=')) {
    window.history.replaceState(null, '', window.location.pathname)
  }

  if (authenticated) {
    // Auto-refresh token before it expires
    setInterval(async () => {
      try {
        await keycloak.updateToken(30)
      } catch {
        keycloak.login()
      }
    }, 10_000)
  }

  return authenticated
}

export function getToken(): string | undefined {
  return keycloak.token
}

export function logout(): void {
  keycloak.logout({ redirectUri: window.location.origin })
}

export function getUserRoles(): string[] {
  return keycloak.realmAccess?.roles ?? []
}

export { keycloak }

import { createApp } from 'vue'
import Toast from 'vue-toastification'
import 'vue-toastification/dist/index.css'
import './style.css'
import App from './App.vue'
import router from './router'
import { initAuth } from './auth'

initAuth().then((authenticated) => {
  if (authenticated) {
    const app = createApp(App)
    app.use(router)
    app.use(Toast, {
      position: 'top-right',
      timeout: 4000,
      closeOnClick: true,
      pauseOnHover: true,
    })
    app.mount('#app')
  }
})

